CREATE TRIGGER RefCusCodeOrAttributeTransportMode_Combined
	ON RefCusCodeOrAttributeTransportMode
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZU_DataSetPK = COALESCE(inserted.ZZU_ZZD_CodeList, ZZE_ZZD_CodeList),
		ZZU_DataSetCode = CASE WHEN inserted.ZZU_ZZD_CodeList IS NOT NULL THEN 'ZZD' ELSE CASE WHEN ZZE_ZZD_CodeList IS NOT NULL THEN 'ZZD' END END 
		FROM RefCusCodeOrAttributeTransportMode t
		JOIN inserted ON t.ZZU_PK = inserted.ZZU_PK
		LEFT JOIN RefCusCodeListAttribute ON inserted.ZZU_ZZE_Attribute = ZZE_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZU_DataSetPK, t.ZZU_DataSetCode
	FROM RefCusCodeOrAttributeTransportMode t
	JOIN inserted ON t.ZZU_PK = inserted.ZZU_PK
	UNION
	SELECT ZZU_DataSetPK, ZZU_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

